+++ b/internal/cache/client.go
@@ -2,18 +2,40 @@ package cache

 import (
 	"errors"
+	"math/rand"
 	"time"
 )

 var ErrUnavailable = errors.New("cache unavailable")

+const (
+	maxAttempts = 10
+	baseDelay   = 50 * time.Millisecond
+	maxDelay    = 2 * time.Second
+)
+
 func (c *Client) Get(key string) ([]byte, error) {
-	for attempt := 0; attempt < 5; attempt++ {
+	for attempt := 0; attempt < maxAttempts; attempt++ {
 		v, err := c.conn.Get(key)
 		if err == nil {
 			return v, nil
 		}
-		time.Sleep(time.Duration(attempt*attempt) * 50 * time.Millisecond)
+		if attempt == maxAttempts-1 {
+			break
+		}
+		time.Sleep(backoff(attempt))
 	}
 	return nil, ErrUnavailable
 }
+
+// backoff returns a jittered delay that grows exponentially with attempt,
+// capped at maxDelay. Full jitter (as opposed to a fixed schedule) spreads
+// out retries from concurrent callers so they don't hammer the cluster in
+// lockstep during a load spike.
+func backoff(attempt int) time.Duration {
+	ceiling := baseDelay * time.Duration(uint64(1)<<uint(attempt))
+	if ceiling <= 0 || ceiling > maxDelay {
+		ceiling = maxDelay
+	}
+	return time.Duration(rand.Int63n(int64(ceiling) + 1))
+}

