 		}
-		time.Sleep(time.Duration(attempt*attempt) * 50 * time.Millisecond)
+		lastErr = err
+
+		if attempt == maxAttempts-1 {
+			break
+		}
+		time.Sleep(jitteredBackoff(attempt))
+	}
+	return nil, fmt.Errorf("%w: %v", ErrUnavailable, lastErr)
+}
+
+// jitteredBackoff returns a randomized delay so that many callers retrying
+// at once (e.g. during a load spike) spread their requests out over time
+// instead of retrying in lockstep and re-creating the synchronized retry
+// storm from INC-2019-07.
