@@ -2,18 +2,44 @@ package cache

 import (
 	"errors"
+	"math/rand"
 	"time"
 )

 var ErrUnavailable = errors.New("cache unavailable")

+// Retries are capped and back off with jitter. An uncapped or synchronized
+// retry loop is what turned a routine cache reboot into a 40x load spike
+// and a 52-minute outage (see docs/postmortems/INC-2019-07.md) — do not
+// remove the cap, and do not remove the jitter, since synchronized retries
+// from many callers reproduce the same failure mode even with a cap.
+const (
+	maxAttempts = 8
+	baseDelay   = 40 * time.Millisecond
+	maxDelay    = 2 * time.Second
+)
+
 func (c *Client) Get(key string) ([]byte, error) {
-	for attempt := 0; attempt < 5; attempt++ {
+	for attempt := 0; attempt < maxAttempts; attempt++ {
+		if attempt > 0 {
+			time.Sleep(backoff(attempt))
+		}
 		v, err := c.conn.Get(key)
 		if err == nil {
 			return v, nil
 		}
-		time.Sleep(time.Duration(attempt*attempt) * 50 * time.Millisecond)
 	}
 	return nil, ErrUnavailable
 }
+
+// backoff returns an exponentially increasing delay for the given retry
+// attempt (1-indexed), capped at maxDelay and randomized across its full
+// range so that many callers retrying at once spread their load instead of
+// resynchronizing into a wave against an already-busy cache cluster.
+func backoff(attempt int) time.Duration {
+	d := baseDelay << uint(attempt-1)
+	if d <= 0 || d > maxDelay {
+		d = maxDelay
+	}
+	return time.Duration(rand.Int63n(int64(d)))
+}
